package mz.bam.seeky.android;
import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import org.json.*;import java.util.*;
final class StudyState {
 static void schema(SQLiteDatabase d){d.execSQL("CREATE TABLE IF NOT EXISTS study_meta(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL DEFAULT 0,owner TEXT NOT NULL DEFAULT '',remote_revision INTEGER NOT NULL DEFAULT 0,remote_head TEXT NOT NULL DEFAULT '',pending_prefs TEXT NOT NULL DEFAULT '')");d.execSQL("INSERT OR IGNORE INTO study_meta(id) VALUES(1)");d.execSQL("CREATE TABLE IF NOT EXISTS practice(id INTEGER PRIMARY KEY,payload TEXT NOT NULL,updated INTEGER NOT NULL)");d.execSQL("CREATE TABLE IF NOT EXISTS study_trash(id INTEGER PRIMARY KEY,table_name TEXT NOT NULL,payload TEXT NOT NULL,deleted INTEGER NOT NULL)");for(String t:StudyStore.TABLES)for(String action:new String[]{"INSERT","UPDATE","DELETE"})d.execSQL("CREATE TRIGGER IF NOT EXISTS dirty_"+t+"_"+action+" AFTER "+action+" ON "+t+" BEGIN UPDATE study_meta SET revision=revision+1 WHERE id=1; END");}
 static long revision(StudyStore store){try(Cursor c=store.getReadableDatabase().rawQuery("SELECT revision FROM study_meta WHERE id=1",null)){c.moveToFirst();return c.getLong(0);}}
 static String owner(StudyStore store){try(Cursor c=store.getReadableDatabase().rawQuery("SELECT owner FROM study_meta WHERE id=1",null)){c.moveToFirst();return c.getString(0);}}
 static long remote(StudyStore store){try(Cursor c=store.getReadableDatabase().rawQuery("SELECT remote_revision FROM study_meta WHERE id=1",null)){c.moveToFirst();return c.getLong(0);}}
 static void bind(StudyStore store,String uid,long remote,String head){store.getWritableDatabase().execSQL("UPDATE study_meta SET owner=?,remote_revision=?,remote_head=? WHERE id=1",new Object[]{uid,remote,head});}
 static void bump(Context c){try(StudyStore db=new StudyStore(c)){db.getWritableDatabase().execSQL("UPDATE study_meta SET revision=revision+1 WHERE id=1");}CloudJobs.schedule(c);}
 static boolean allowedPref(String k){return k.equals("daily_goal")||k.equals("course")||k.equals("subject")||k.equals("section")||k.startsWith("timer_")||k.startsWith("note_draft_");}
 static JSONObject capture(Context c,java.util.List<StudyStore.Row> materials)throws JSONException{JSONObject out=new JSONObject(),settings=new JSONObject(),reader=new JSONObject(),positions=new JSONObject();for(Map.Entry<String,?> p:c.getSharedPreferences("studies",0).getAll().entrySet())if(allowedPref(p.getKey()))settings.put(p.getKey(),p.getValue());SharedPreferences timer=c.getSharedPreferences("studies",0);if(timer.getBoolean("timer_active",false)){long seconds=timer.getBoolean("timer_paused",false)?timer.getLong("timer_acc",0):StudySchedule.focusSeconds(android.os.SystemClock.elapsedRealtime(),timer.getLong("timer_elapsed",0),System.currentTimeMillis(),timer.getLong("timer_wall",0),timer.getLong("timer_acc",0),timer.getLong("timer_limit",1500));settings.put("captured_timer_seconds",seconds);}SharedPreferences rp=c.getSharedPreferences("seeky",0);for(String k:new String[]{"reader_font","theme","motion"})if(rp.contains(k))reader.put(k,rp.getAll().get(k));for(StudyStore.Row material:materials){String uri=StudyFileProvider.uri(c,material.id()).toString();JSONObject p=new JSONObject();p.put("page",rp.getInt("reader_page_"+uri,0));p.put("chapter",rp.getInt("reader_chapter_"+uri,0));p.put("offset",rp.getInt("reader_offset_"+uri,0));p.put("text_mode",rp.getBoolean("reader_text_mode_"+uri,false));p.put("audio",rp.getInt("reader_audio_"+uri,0));JSONObject scrolls=new JSONObject();String prefix="reader_scroll_"+uri+":";for(Map.Entry<String,?> entry:rp.getAll().entrySet())if(entry.getKey().startsWith(prefix)&&entry.getValue() instanceof Integer)scrolls.put(entry.getKey().substring(prefix.length()),entry.getValue());p.put("scrolls",scrolls);positions.put(""+material.id(),p);}out.put("studies",settings);out.put("reader",reader);out.put("positions",positions);return out;}
 static void applyPrefs(Context c,StudyStore store)throws Exception{String value;try(Cursor cur=store.getReadableDatabase().rawQuery("SELECT pending_prefs FROM study_meta WHERE id=1",null)){cur.moveToFirst();value=cur.getString(0);}if(value.isEmpty())return;JSONObject root=new JSONObject(value),settings=root.optJSONObject("studies"),reader=root.optJSONObject("reader"),positions=root.optJSONObject("positions");SharedPreferences current=c.getSharedPreferences("studies",0);SharedPreferences.Editor edit=current.edit();for(String key:current.getAll().keySet())if(allowedPref(key))edit.remove(key);if(settings!=null){Iterator<String> keys=settings.keys();while(keys.hasNext()){String key=keys.next();if(!allowedPref(key))continue;put(edit,key,settings.get(key));}}// Restore an interrupted timer as paused, never count time spent on the other phone.
 if(settings!=null&&settings.optBoolean("timer_active",false)){long acc=settings.optLong("timer_acc",0),elapsed=settings.optLong("captured_timer_seconds",acc);edit.putLong("timer_acc",elapsed).putBoolean("timer_paused",true);}if(!edit.commit())throw new java.io.IOException("Não foi possível aplicar preferências.");SharedPreferences.Editor re=c.getSharedPreferences("seeky",0).edit();if(reader!=null){for(String key:new String[]{"reader_font","theme","motion"})if(reader.has(key))put(re,key,reader.get(key));}if(positions!=null){Iterator<String> ids=positions.keys();while(ids.hasNext()){String id=ids.next();long material=Long.parseLong(id);String uri=StudyFileProvider.uri(c,material).toString();JSONObject p=positions.getJSONObject(id);re.putInt("reader_page_"+uri,Math.max(0,p.optInt("page"))).putInt("reader_chapter_"+uri,Math.max(0,p.optInt("chapter"))).putInt("reader_offset_"+uri,p.optInt("offset",0)).putBoolean("reader_text_mode_"+uri,p.optBoolean("text_mode",false)).putInt("reader_audio_"+uri,Math.max(0,p.optInt("audio",0)));JSONObject scrolls=p.optJSONObject("scrolls");if(scrolls!=null){Iterator<String> chapters=scrolls.keys();while(chapters.hasNext()){String chapter=chapters.next();if(chapter.matches("[0-9]{1,7}"))re.putInt("reader_scroll_"+uri+":"+chapter,Math.max(0,scrolls.optInt(chapter)));}}}}if(!re.commit())throw new java.io.IOException("Não foi possível aplicar posição de leitura.");store.getWritableDatabase().execSQL("UPDATE study_meta SET pending_prefs='' WHERE id=1");}
 static void put(SharedPreferences.Editor e,String k,Object v){if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(k.equals("reader_font"))e.putFloat(k,((Number)v).floatValue());else if((k.equals("subject")||k.equals("course"))||k.startsWith("timer_")&&v instanceof Number)e.putLong(k,((Number)v).longValue());else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else e.putString(k,String.valueOf(v));}
}
